package com.asmj.marketplace.audit;
import java.time.Instant; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document;
@Document(collection="marketplace_audit_events") public class AuditEvent { @Id private String id; @Indexed private Instant createdAt=Instant.now(); private String actor,role,action,entityType,entityId,details; public String getId(){return id;} public void setId(String v){id=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public String getActor(){return actor;} public void setActor(String v){actor=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public String getAction(){return action;} public void setAction(String v){action=v;} public String getEntityType(){return entityType;} public void setEntityType(String v){entityType=v;} public String getEntityId(){return entityId;} public void setEntityId(String v){entityId=v;} public String getDetails(){return details;} public void setDetails(String v){details=v;} }
